INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_ec_2025_s1_q1', 'GATE', 'EC', '', 2025, '1', 1, 'subj_EC_ga', '', '', 'MCQ', 1, 0, 'Here are two analogous groups, Group-I and Group-II, that list words in their decreasing order of intensity. Identify the missing word in Group-II. Group-I: Abuse Insult Ridicule Group-II: ________ Praise Appreciate', ARRAY[ARRAY['Extol'], ARRAY['Prize'], ARRAY['Appropriate'], ARRAY['Espouse']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_ec_2025_s1_q2', 'GATE', 'EC', '', 2025, '1', 2, 'subj_EC_ga', '', '', 'MCQ', 1, 0, 'Had I learnt acting as a child, I ________ a famous film star. Select the most appropriate option to complete the above sentence.', ARRAY[ARRAY['will be'], ARRAY['can be'], ARRAY['am going to be'], ARRAY['could have been']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_ec_2025_s1_q3', 'GATE', 'EC', '', 2025, '1', 3, 'subj_EC_ga', '', '', 'MCQ', 1, 0, 'The 12 musical notes are given as , #, , #, , , #, , #, , #, and . Frequency of each note is 122 times the frequency of the previous note. If the frequency of the note C is 130.8 Hz, then the ratio of frequencies of notes # and is:', ARRAY[ARRAY['62'], ARRAY['2'], ARRAY['42'], ARRAY['2']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_ec_2025_s1_q4', 'GATE', 'EC', '', 2025, '1', 4, 'subj_EC_ga', '', '', 'MCQ', 1, 0, 'The following figures show three curves generated using an iterative algorithm. The total length of the curve generated after `Iteration '' is: Note: The figures shown are representative. 1 Iteration 0: Iteration 1: 1 1 Length of each segment: 3 3 1 1 Iteration 2: 9 Length of each segment: 9', ARRAY[ARRAY['5'], ARRAY['5 2'], ARRAY['5 (2-1)']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_ec_2025_s1_q5', 'GATE', 'EC', '', 2025, '1', 5, 'subj_EC_ga', '', '', 'MCQ', 2, 0, 'Which one of the following plots represents () = - ||, where is a non- zero real number? Note: The figures shown are representative.', NULL, NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_ec_2025_s1_q6', 'GATE', 'EC', '', 2025, '1', 6, 'subj_EC_ec', '', '', 'MCQ', 2, 0, 'Identify the option that has the most appropriate sequence such that a coherent paragraph is formed: P. Over time, such adaptations lead to significant evolutionary changes with the potential to shape the development of new species. Q. In natural world, organisms constantly adapt to their environments in response to challenges and opportunities. R. This process of adaptation is driven by the principle of natural selection, where favorable traits increase an organism''s chances of survival and reproduction. S. As environments change, organisms that can adapt their behavior, structure and physiology to such changes are more likely to survive.', ARRAY[ARRAY['P Q R S'], ARRAY['Q S R P'], ARRAY['R S Q P'], ARRAY['S P R Q']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_ec_2025_s1_q7', 'GATE', 'EC', '', 2025, '1', 7, 'subj_EC_ec', '', '', 'MCQ', 2, 0, 'A stick of length one meter is broken at two locations at distances of 1 and 2 from the origin (0), as shown in the figure. Note that 0 < 1 < 2 < 1. Which one of the following is NOT a necessary condition for forming a triangle using the three pieces? Note: All lengths are in meter. The figure shown is representative.', ARRAY[ARRAY['1 < 0.5'], ARRAY['2 > 0.5'], ARRAY['2 < 1 + 0.5'], ARRAY['1 + 2 < 1']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_ec_2025_s1_q8', 'GATE', 'EC', '', 2025, '1', 8, 'subj_EC_ec', '', '', 'MCQ', 2, 0, 'Eight students (P, Q, R, S, T, U, V, and W) are playing musical chairs. The figure indicates their order of position at the start of the game. They play the game by moving forward in a circle in the clockwise direction. After the 1st round, 4th student behind P leaves the game. After 2nd round, 5th student behind Q leaves the game. After 3rd round, 3rd student behind V leaves the game. After 4th round, 4th student behind U leaves the game. Who all are left in the game after the 4th round? Note: The figure shown is representative. P W R U T V Q S', ARRAY[ARRAY['P; T; Q; S'], ARRAY['V; P; T; Q'], ARRAY['W; R; Q; V'], ARRAY['Q; T; V; W']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_ec_2025_s1_q9', 'GATE', 'EC', '', 2025, '1', 9, 'subj_EC_ec', '', '', 'MCQ', 2, 0, 'The table lists the top 5 nations according to the number of gold medals won in a tournament; also included are the number of silver and the bronze medals won by them. Based only on the data provided in the table, which one of the following statements is INCORRECT? Nation Gold Silver Bronze USA 40 44 41 Canada 39 27 24 Japan 20 12 13 Australia 17 19 16 France 16 26 22', ARRAY[ARRAY['France will occupy the third place if the list were made on the basis of the total'], ARRAY['The order of the top two nations will not change even if the list is made on the basis'], ARRAY['USA and Canada together have less than 50% of the medals awarded to the nations'], ARRAY['Canada has won twice as many total medals as Japan.']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_ec_2025_s1_q10', 'GATE', 'EC', '', 2025, '1', 10, 'subj_EC_ec', '', '', 'MCQ', 2, 0, 'An organization allows its employees to work independently on consultancy projects but charges an overhead on the consulting fee. The overhead is 20% of the consulting fee, if the fee is up to 5,00,000. For higher fees, the overhead is 1,00,000 plus 10% of the amount by which the fee exceeds 5,00,000. The government charges a Goods and Services Tax of 18% on the total amount (the consulting fee plus the overhead). An employee of the organization charges this entire amount, i.e., the consulting fee, overhead, and tax, to the client. If the client cannot pay more than 10,00,000, what is the maximum consulting fee that the employee can charge?', ARRAY[ARRAY['7,01,438'], ARRAY['7,24,961'], ARRAY['7,51,232'], ARRAY['7,75,784']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_ec_2025_s1_q11', 'GATE', 'EC', '', 2025, '1', 11, 'subj_EC_ec', '', '', 'MCQ', 2, 0, 'Consider the matrix below: 2 34 5 = [ 0 67 8 ] 0 0 0 0 0 For which of the following combinations of , , and , is the rank of at least three? (i) = 0 and = 0. (ii) = = = 0. (iii) = = 0 and 0. (iv) = = 0.', ARRAY[ARRAY['Only (i), (iii), and (iv)'], ARRAY['Only (iv)'], ARRAY['Only (ii)'], ARRAY['Only (i) and (iii)']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_ec_2025_s1_q12', 'GATE', 'EC', '', 2025, '1', 12, 'subj_EC_ec', '', '', 'MCQ', 2, 0, 'Consider the following series: (i) =1 1 (ii) =1 1 (+1) (iii) =1 1 ! Choose the correct option.', ARRAY[ARRAY['Only (ii) converges'], ARRAY['Only (ii) and (iii) converge'], ARRAY['Only (iii) converges'], ARRAY['All three converge']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
