INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_ec_2025_s1_q25', 'GATE', 'EC', '', 2025, '1', 25, 'subj_EC_ec', '', '', 'MCQ', 2, 0, 'Consider the function : , defined as () = 23 - 32 - 12 + 1. Which of the following statements is/are correct? (Here, is the set of real numbers.)', ARRAY[ARRAY['has no global maximizer'], ARRAY['has no global minimizer'], ARRAY['= -1 is a local minimizer of'], ARRAY['= 2 is a local maximizer of']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
