INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_ec_2025_s1_q28', 'GATE', 'EC', '', 2025, '1', 28, 'subj_EC_ec', '', '', 'MCQ', 2, 0, 'Consider a message signal () which is bandlimited to [-, ], where is in Hz. Consider the following two modulation schemes for the message signal: � Double sideband-suppressed carrier (DSB-SC): () = () cos(2) � Amplitude modulation (AM): () = (1 + ()) cos(2) Here, and are the amplitude and frequency (in Hz) of the carrier, respectively. In the case of AM, denotes the modulation index. Consider the following statements: (i) An envelope detector can be used for demodulation in the DSB-SC scheme if () > 0 for all . (ii) An envelope detector can be used for demodulation in the AM scheme only if () > 0 for all . Which of the following options is/are correct?', ARRAY[ARRAY['(i) is TRUE'], ARRAY['(i) is FALSE'], ARRAY['(ii) is TRUE'], ARRAY['(ii) is FALSE']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_ec_2025_s1_q29', 'GATE', 'EC', '', 2025, '1', 29, 'subj_EC_ec', '', '', 'MCQ', 2, 0, 'Which of the following statements is/are TRUE with respect to an ideal opamp?', ARRAY[ARRAY['It has an infinite input resistance'], ARRAY['It has an infinite output resistance'], ARRAY['It has an infinite open-loop differential gain'], ARRAY['It has an infinite open-loop common-mode gain']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_ec_2025_s1_q30', 'GATE', 'EC', '', 2025, '1', 30, 'subj_EC_ec', '', '', 'MCQ', 2, 0, 'Which of the following statements is/are TRUE with respect to ideal MOSFET- based DC-coupled single-stage amplifiers having finite load resistors?', ARRAY[ARRAY['The common-gate amplifier has an infinite input resistance'], ARRAY['The common-source amplifier has an infinite input resistance'], ARRAY['The input and output voltages of the common-source amplifier are in phase'], ARRAY['The input and output voltages of the common-drain amplifier are in phase']]::text[], NULL, 2, 'GATE Official 2025 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2025/', 'official', 2025, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
